// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';

// ---- inlined from bloom ----
/**
 * Bloom filter trace: a 256-bit array, k=3 FNV-1a hashes. Fifteen inserts light bits,
 * then a scripted query mix runs: members hit all three bits, true negatives bounce off
 * the first dark bit, and one word never inserted — found by honestly scanning the
 * candidate pool — hits three bits other words set. SALT was chosen so exactly one such
 * false positive exists in the pool; the scan below rediscovers it rather than naming it.
 */

const BLOOM_BITS = 256;
const BLOOM_COLS = 32;
const BLOOM_ROWS = 8;

const SALT = 28;
const SEEDS = [0x811c9dc5, 0x01000193, 0x7feb352d];

function bloomHashes(word: string): number[] {
  return SEEDS.map((seed) => {
    let h = (seed ^ SALT) >>> 0;
    for (let i = 0; i < word.length; ++i) {
      h ^= word.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return (h >>> 0) % BLOOM_BITS;
  });
}

const INSERTS = [
  'RIVER', 'STONE', 'MAPLE', 'FALCON', 'EMBER', 'GLACIER', 'MEADOW', 'THUNDER',
  'VIOLET', 'COPPER', 'HARBOR', 'JUNIPER', 'SPARROW', 'WILLOW', 'CANYON'
];

/** Words never inserted; queries draw true negatives and the false positive from here. */
const POOL = [
  'ORCHID', 'BASALT', 'TUNDRA', 'PYRITE', 'LAGOON', 'THISTLE', 'MARBLE', 'GRANITE',
  'COBALT', 'SUMMIT', 'NEBULA', 'QUARRY', 'TIMBER', 'VELVET', 'WALNUT', 'ZEPHYR'
];

interface BloomEvent {
  kind: 'insert' | 'member' | 'absent' | 'false-positive';
  word: string;
  /** The k bit indices this word hashes to. */
  bits: number[];
  /** For 'absent': the first unset bit that proves the word was never inserted. */
  missing: number;
  /** Bits set after this event. */
  setCount: number;
}

const allSet = new Set<number>();
const events: BloomEvent[] = [];

for (const word of INSERTS) {
  const bits = bloomHashes(word);
  for (const b of bits) allSet.add(b);
  events.push({ kind: 'insert', word, bits, missing: -1, setCount: allSet.size });
}

const collides = (word: string) => bloomHashes(word).every((b) => allSet.has(b));
const falsePositive = POOL.find(collides) ?? POOL[0];
const negatives = POOL.filter((word) => !collides(word));

const QUERIES = [
  'WILLOW', negatives[0], negatives[1], 'FALCON',
  negatives[2], falsePositive, negatives[3], 'COPPER'
];

for (const word of QUERIES) {
  const bits = bloomHashes(word);
  const missing = bits.find((b) => !allSet.has(b)) ?? -1;
  const kind =
    missing >= 0 ? 'absent' : INSERTS.includes(word) ? 'member' : 'false-positive';
  events.push({ kind, word, bits, missing, setCount: allSet.size });
}

const bloomEvents = events;

const TICK_MS = 120;
const TICKS_PER_EVENT = 6;
const HOLD_TICKS = 24;
const END = bloomEvents.length * TICKS_PER_EVENT;
const PRESENT = '#3fa66a';
const HOT = '#e0538a';

export default function BloomFilter({ width }: { width: number }) {
  const cell = Math.max(1, width) / BLOOM_COLS;
  const gridHeight = cell * BLOOM_ROWS;
  const height = Math.round(30 + gridHeight + 22);

  // The SSR frame is the whole script played out; the effect rewinds and replays it.
  const [tick, setTick] = useState(END);

  useEffect(() => {
    setTick(0);
    const id = window.setInterval(
      () => setTick((t) => (t >= END + HOLD_TICKS ? 0 : t + 1)),
      TICK_MS
    );
    return () => window.clearInterval(id);
  }, []);

  const bitSquare = useMemo(() => {
    const inset = cell * 0.1;
    const side = cell - 2 * inset;
    return (b: number) =>
      `M${((b % BLOOM_COLS) * cell + inset).toFixed(1)},${(((b / BLOOM_COLS) | 0) * cell + inset).toFixed(1)}h${side.toFixed(1)}v${side.toFixed(1)}h${(-side).toFixed(1)}Z`;
  }, [cell]);

  const background = useMemo(
    () => Array.from({ length: BLOOM_BITS }, (_, b) => bitSquare(b)).join(''),
    [bitSquare]
  );

  const count = Math.min(Math.ceil(tick / TICKS_PER_EVENT), bloomEvents.length);
  const current = count > 0 ? bloomEvents[count - 1] : null;

  const setPath = useMemo(() => {
    const bits = new Set<number>();
    for (let k = 0; k < count; ++k) {
      if (bloomEvents[k].kind === 'insert') for (const b of bloomEvents[k].bits) bits.add(b);
    }
    return { d: [...bits].map(bitSquare).join(''), size: bits.size };
  }, [count, bitSquare]);

  if (width === 0) return null;

  const fillRate = setPath.size / BLOOM_BITS;
  const odds = (fillRate ** 3 * 100).toFixed(1);
  const headline = !current
    ? ''
    : current.kind === 'insert'
      ? `insert "${current.word}"`
      : current.kind === 'member'
        ? `query "${current.word}" → probably present`
        : current.kind === 'absent'
          ? `query "${current.word}" → definitely absent · bit ${current.missing} was never set`
          : `query "${current.word}" → "probably present" · but ${current.word} was never inserted`;
  const headlineColor =
    current?.kind === 'false-positive'
      ? HOT
      : current?.kind === 'member'
        ? PRESENT
        : current?.kind === 'absent'
          ? 'var(--muted)'
          : 'var(--text)';

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="A Bloom filter's 256-bit array lighting up as fifteen words are inserted through three hashes, then queried: members hit all three of their bits, true negatives bounce off one dark bit, and one word never inserted lands on three bits set by other words — the false positive the filter trades space for"
    >
      <text x={4} y={16} fill={headlineColor} fontSize={12} fontWeight={current?.kind === 'false-positive' ? 700 : 600}>
        {headline}
      </text>
      <g transform="translate(0,26)">
        <path d={background} fill="var(--muted)" opacity={0.12} />
        <path d={setPath.d} fill="var(--accent)" opacity={0.8} />
        {current?.kind === 'insert' &&
          current.bits.map((b) => <path key={b} d={bitSquare(b)} fill={HOT} opacity={0.9} />)}
        {current?.kind === 'member' &&
          current.bits.map((b) => <path key={b} d={bitSquare(b)} fill={PRESENT} opacity={0.9} />)}
        {current?.kind === 'false-positive' &&
          current.bits.map((b) => <path key={b} d={bitSquare(b)} fill={HOT} opacity={0.95} />)}
        {current?.kind === 'absent' &&
          current.bits.map((b) =>
            b === current.missing ? (
              <path
                key={b}
                d={bitSquare(b)}
                fill="none"
                stroke={PRESENT}
                strokeWidth={Math.max(1, cell * 0.12)}
              />
            ) : (
              <path key={b} d={bitSquare(b)} fill={PRESENT} opacity={0.4} />
            )
          )}
      </g>
      <text x={4} y={height - 6} fill="var(--muted)" fontSize={11}>
        {`${setPath.size} of ${BLOOM_BITS} bits set`}
      </text>
      <text x={width - 4} y={height - 6} textAnchor="end" fill="var(--muted)" fontSize={11}>
        {`odds a random word collides: ${odds}%`}
      </text>
    </svg>
  );
}
